    "partOfSpeech": "名词",
    "partOfSpeechGroup": "noun",
    "pitch": "②型",
    "needsExplanation": false,
    "meaning": "故乡、家乡；指出生或成长的地方，也可指自己有深厚感情、视为归属之地的地方。汉字常写作「故郷」。",
