    "key": "claim",
    "lesson": 3,
    "order": 3,
    "word": "クレーム",
    "reading": "クレーム",
    "partOfSpeech": "名词",
    "partOfSpeechGroup": "noun",
    "pitch": "⓪型",
    "needsExplanation": false,
    "meaning": "投诉、客诉；在日语中主要指顾客因商品或服务有问题而提出的不满或要求。常用「クレームを入れる」「クレームに対応する」，不等同于英语 claim 的所有含义。",
