        "jaHtml": "<ruby>商<rt>しょう</rt></ruby><ruby>品<rt>ひん</rt></ruby>の<ruby>破<rt>は</rt></ruby><ruby>損<rt>そん</rt></ruby>について、<ruby>客<rt>きゃく</rt></ruby>から<strong>クレーム</strong>が<ruby>寄<rt>よ</rt></ruby>せられました。",
