    "partOfSpeechGroup": "noun-verb",
    "pitch": "⓪型",
    "needsExplanation": false,
    "meaning": "转播、现场连线；指通过通信设备把远处的画面、声音或比赛实况传送给观众。常用「生中継」「中継をつなぐ」「試合を中継する」。",
